<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function relp($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}
function blocked($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return true;return false;}
function scan_site($root){global $TEXT;$files=[];$dirs=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=relp($f->getPathname(),$root);if(!$p||blocked($p)||$p==='site-wire-live.php')continue;if($f->isDir())$dirs[]=$p;elseif($f->isFile())$files[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}sort($dirs);ksort($files);$refs=[];$rx=['/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i','/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i','/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];foreach($files as $p=>$m){if(!$m['text']||$m['size']>700000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($files[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}return ['files'=>array_keys($files),'dirs'=>$dirs,'refs'=>$refs,'time'=>date('H:i:s')];}
$D=scan_site($ROOT);if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>date('H:i:s'),'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}if(isset($_GET['data'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($D,JSON_UNESCAPED_SLASHES);exit;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — Relationship Manager</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:#071016;color:#dcecf2;font-family:Inter,system-ui,Segoe UI,Arial}body{background:radial-gradient(ellipse at 50% 48%,#10252d 0,#071016 48%,#04080b 100%)}#map{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.top{position:fixed;z-index:4;left:24px;right:24px;top:20px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.brand{font-size:20px;font-weight:800}.brand b{color:#55dfcb}.sub{margin-top:5px;color:#627c87;font:8px ui-monospace;letter-spacing:1.4px}.stats{display:flex;gap:7px}.stat,.search,.panel,.button{background:#09171de8;border:1px solid #7599a51f;border-radius:10px;backdrop-filter:blur(14px)}.stat{padding:7px 10px}.stat small{display:block;color:#58727d;font:7px ui-monospace}.stat strong{font:11px ui-monospace}.live{color:#59e4b5}.search{position:fixed;z-index:5;left:24px;top:82px;width:260px;padding:11px 12px;color:#eaffff;outline:0;font:9px ui-monospace}.panel{display:none;position:fixed;z-index:8;right:24px;top:82px;width:320px;padding:16px}.panel.show{display:block}.close{float:right;border:0;background:none;color:#6c858f;font-size:19px;cursor:pointer}.eyebrow{color:#587680;font:7px ui-monospace;letter-spacing:1.5px}.panel h2{font-size:15px;margin:8px 0 3px}.path{color:#61ddd1;font:8px ui-monospace;word-break:break-all}.relations{margin-top:12px;color:#78919a;font:8px ui-monospace;line-height:1.8;max-height:300px;overflow:auto}.relations b{color:#c7d9de}.bottom{position:fixed;z-index:5;left:24px;bottom:20px;display:flex;gap:6px}.button{padding:9px 12px;color:#a0b7bf;font:800 8px ui-monospace;cursor:pointer}.button:hover{color:#eaffff;border-color:#55dfcb55}.status{position:fixed;z-index:5;right:24px;bottom:23px;color:#627b85;font:8px ui-monospace}.load{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#04090df7}.loader{text-align:center}.loader span{display:block;color:#cfe2e7;font-size:10px;font-weight:700;margin-top:10px}.loader small{display:block;color:#58717c;font:8px ui-monospace;margin-top:5px}@media(max-width:700px){.top{left:12px;right:12px}.brand{font-size:16px}.sub{display:none}.stats .stat:nth-child(n+3){display:none}.search{left:12px;top:68px;width:205px}.panel{left:12px;right:12px;top:68px;width:auto}.bottom{left:12px;bottom:12px}.status{right:12px;bottom:53px}}
</style></head><body><div class="load" id="load"><div class="loader"><span>SmartToolz Relationship Manager</span><small>Reading live server filesystem…</small></div></div><div class="top"><div><div class="brand"><b>◇</b> SmartToolz <span>Relationship Manager</span></div><div class="sub">ACTUAL FILES • ACTUAL REFERENCES • LIVE SERVER</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="files">0</strong></div><div class="stat"><small>RELATIONS</small><strong id="rels">0</strong></div><div class="stat"><small>SERVER</small><strong class="live" id="state">LIVE</strong></div></div></div><input class="search" id="search" placeholder="Search a file or folder…"><svg id="map" xmlns="http://www.w3.org/2000/svg"></svg><div class="panel" id="panel"><button class="close" id="close">×</button><div class="eyebrow">RELATIONSHIP DETAILS</div><h2 id="name"></h2><div class="path" id="path"></div><div class="relations" id="relations"></div></div><div class="bottom"><button class="button" id="center">CENTER</button><button class="button" id="refresh">REFRESH</button></div><div class="status">SERVER <b id="hb">CONNECTING</b></div><script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>,svg=document.getElementById('map');let W=innerWidth,H=innerHeight,zoom=.78,panX=0,panY=0,drag=false,lx=0,ly=0,nodes=[],edges=[],selected=null,hover=null;
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function build(){const all=[...D.dirs.map(path=>({id:'d:'+path,path,name:path.split('/').pop()+'/',folder:1})),...D.files.map(path=>({id:'f:'+path,path,name:path.split('/').pop(),folder:0}))];const by=new Map(all.map(n=>[n.id,n]));nodes=all;edges=[];for(const n of nodes){const parts=n.path.split('/');if(parts.length>1){const parent=parts.slice(0,-1).join('/');if(by.has('d:'+parent))edges.push({a:by.get('d:'+parent),b:n,type:'tree'})}}for(const r of D.refs){const a=by.get('f:'+r.from),b=by.get('f:'+r.to);if(a&&b)edges.push({a,b,type:'dep'})}document.getElementById('files').textContent=D.files.length;document.getElementById('rels').textContent=D.refs.length;document.getElementById('load').style.display='none';render()}
function layout(){const cx=W/2,cy=H/2,folders=nodes.filter(n=>n.folder),R=Math.min(W,H)*.27;folders.forEach((n,i)=>{const a=i/Math.max(1,folders.length)*Math.PI*2-Math.PI/2;n.x=cx+Math.cos(a)*R;n.y=cy+Math.sin(a)*R});folders.forEach(f=>{const kids=nodes.filter(n=>!n.folder&&n.path.startsWith(f.path+'/'));const R2=Math.min(W,H)*.11;const a=Math.atan2(f.y-cy,f.x-cx),span=Math.min(1.25,Math.max(.3,kids.length*.018));kids.forEach((n,i)=>{const q=a-span/2+(i/Math.max(1,kids.length-1))*span;n.x=f.x+Math.cos(q)*R2;n.y=f.y+Math.sin(q)*R2})});nodes.filter(n=>!n.folder&&!n.path.includes('/')).forEach((n,i,a)=>{const q=i/Math.max(1,a.length)*Math.PI*2;n.x=cx+Math.cos(q)*Math.min(W,H)*.15;n.y=cy+Math.sin(q)*Math.min(W,H)*.15})}
function point(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}function bend(a,b){const dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,k=Math.min(50,d*.16);return{x:(a.x+b.x)/2-dy/d*k,y:(a.y+b.y)/2+dx/d*k}}
function render(){layout();svg.innerHTML='';const ns=nodes.map(n=>{const p=point(n),w=n.folder?Math.max(72,n.name.length*6.1+24):Math.max(62,n.name.length*5.4+18),h=n.folder?28:24;return{n,p,w,h}});for(const e of edges){const A=point(e.a),B=point(e.b),M=bend(A,B),on=selected&&(e.a===selected||e.b===selected)||hover&&(e.a===hover||e.b===hover);const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${A.x},${A.y} Q${M.x},${M.y} ${B.x},${B.y}`);path.setAttribute('fill','none');path.setAttribute('stroke',on?'#56dfd0':e.type==='dep'?'#3d7e83':'#35434b');path.setAttribute('stroke-width',on?'2.2':e.type==='dep'?'1.1':'.8');path.setAttribute('stroke-linecap','round');if(on)path.setAttribute('stroke-dasharray','7 8');path.style.opacity=on?'0.95':e.type==='dep'?'.32':'.16';if(on)path.style.animation='dash 1.4s linear infinite';svg.appendChild(path)}for(const q of ns){const n=q.n,p=q.p,g=document.createElementNS('http://www.w3.org/2000/svg','g');g.dataset.id=n.id;const r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('x',p.x-q.w/2);r.setAttribute('y',p.y-q.h/2);r.setAttribute('width',q.w);r.setAttribute('height',q.h);r.setAttribute('rx',n.folder?8:6);r.setAttribute('fill',n.folder?'#19172b':'#0b1820');r.setAttribute('stroke',n===selected||n===hover?'#59e4b5':n.folder?'#6f5db5':'#2a4b55');r.setAttribute('stroke-width',n===selected||n===hover?'1.7':'1');r.style.filter=n===selected||n===hover?'drop-shadow(0 0 7px rgba(89,228,181,.45))':'none';g.appendChild(r);const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+3);t.setAttribute('text-anchor','middle');t.setAttribute('fill',n===selected||n===hover?'#eaffff':'#8299a2');t.setAttribute('font-size',n.folder?'9':'8');t.setAttribute('font-family','ui-monospace,monospace');t.textContent=n.name;g.appendChild(t);g.addEventListener('click',ev=>{ev.stopPropagation();select(n)});svg.appendChild(g)} }
function select(n){selected=n;document.getElementById('panel').classList.add('show');document.getElementById('name').textContent=n.folder?'📁 '+n.name:n.name;document.getElementById('path').textContent=n.path;const links=edges.filter(e=>e.a===n||e.b===n).map(e=>e.a===n?e.b:e.a);document.getElementById('relations').innerHTML='<b>'+links.length+' connected items</b><br>'+links.slice(0,80).map(v=>'↳ '+esc(v.path)).join('<br>');render()}
svg.addEventListener('pointerdown',e=>{drag=true;lx=e.clientX;ly=e.clientY;svg.classList.add('drag')});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lx;panY+=e.clientY-ly;lx=e.clientX;ly=e.clientY}else{let best=null,bd=20;for(const n of nodes){const p=point(n);const d=Math.hypot(e.clientX-p.x,e.clientY-p.y);if(d<bd){bd=d;best=n}}if(best!==hover){hover=best;render()}}});addEventListener('pointerup',e=>{drag=false;svg.classList.remove('drag')});svg.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.25,Math.min(2.6,zoom*(e.deltaY<0?1.1:.9)));panX=e.clientX-(e.clientX-panX)*(zoom/old);panY=e.clientY-(e.clientY-panY)*(zoom/old);render()},{passive:false});svg.addEventListener('click',()=>{selected=null;document.getElementById('panel').classList.remove('show');render()});
document.getElementById('close').onclick=()=>{selected=null;document.getElementById('panel').classList.remove('show');render()};document.getElementById('center').onclick=()=>{zoom=.78;panX=0;panY=0;render()};document.getElementById('refresh').onclick=()=>location.reload();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();const n=q?nodes.find(v=>v.path.toLowerCase().includes(q)):null;if(n){select(n);const p=point(n);panX+=W/2-p.x;panY+=H/2-p.y;render()}};
async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&t='+Date.now(),{cache:'no-store'});const d=await r.json();document.getElementById('hb').textContent=d.time;document.getElementById('state').textContent='LIVE'}catch(e){document.getElementById('hb').textContent='OFFLINE';document.getElementById('state').textContent='OFFLINE'}}
addEventListener('resize',()=>{W=innerWidth;H=innerHeight;render()});build();heartbeat();setInterval(heartbeat,2000);
</script><style>@keyframes dash{to{stroke-dashoffset:-30px}}</style></body></html>